"""Validate shell commands generated by the AI before they are accepted or executed.

V1 policy: a command line may chain several commands (`&&`, `||`, `;`, `|`); every command in it
must start with an allowlisted executable and must not match the denylist. Anything else is
rejected - the developer can run it by hand if it is really needed.
"""

import re
import shlex
from collections.abc import Iterable

from pydantic import BaseModel

ALLOWED_EXECUTABLES = frozenset({
    # Python
    "uv", "uvx", "python", "python3", "pip", "pip3", "pytest", "fastapi", "uvicorn",
    "django-admin", "flask", "alembic", "ruff", "mypy", "black", "poetry",
    # JavaScript / TypeScript
    "npm", "npx", "pnpm", "yarn", "node", "bun", "deno", "tsc", "vite", "next", "prisma",
    # Other common toolchains
    "go", "cargo", "rustc", "make", "just", "dotnet", "mvn", "gradle", "ruby", "bundle", "rails",
    "php", "composer", "docker", "sqlite3", "psql",
    # Media tools used by many projects
    "ffmpeg", "ffprobe", "yt-dlp", "youtube-dl", "imagemagick", "magick",
    # Source control and harmless file/terminal utilities
    "git", "mkdir", "touch", "ls", "cat", "echo", "cd", "pwd", "cp", "mv", "clear", "tree",
    "curl", "http", "open", "code", "which", "env", "jq", "grep", "head", "tail", "wc", "sort",
})  # fmt: skip

# (pattern, reason). Checked against the whole command line.
DENY_PATTERNS: list[tuple[re.Pattern[str], str]] = [
    (re.compile(r"\bsudo\b"), "sudo is never allowed"),
    (re.compile(r"\brm\b"), "deleting files from the terminal is not allowed; use a delete_file beat"),
    (re.compile(r"\b(curl|wget)\b[^|]*\|\s*(ba|z|)sh\b"), "piping a download into a shell"),
    (re.compile(r"\b(shutdown|reboot|halt|mkfs\w*|diskutil|dd|fdisk)\b"), "system-level command"),
    (re.compile(r"\bchmod\s+-R\b|\bchown\b"), "recursive permission/ownership changes"),
    (re.compile(r":\(\)\s*\{"), "fork bomb"),
    (re.compile(r"(^|\s)(/|~)(\s|$)"), "operates on the root or home directory"),
    (re.compile(r">\s*/(dev|etc|usr|bin|System)\b"), "writes to a system path"),
    (re.compile(r"\bgit\s+(push|reset\s+--hard|clean)\b"), "destructive or remote git operation"),
    (re.compile(r"\bnpm\s+publish\b|\buv\s+publish\b"), "publishing packages"),
]

_REDIRECTIONS = {"<", ">", ">>", "<<"}
_OPERATORS = {"&&", "||", ";", "|", "&", "(", ")", ";;"}


def split_commands(command: str) -> list[list[str]]:
    """Split a command line into its chained commands' argv lists, respecting quotes."""
    lexer = shlex.shlex(command, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    groups: list[list[str]] = [[]]
    skip_next = False  # the target of a redirection is a file, not a command
    for token in lexer:  # raises ValueError on unbalanced quotes
        if skip_next:
            skip_next = False
            continue
        if token in _REDIRECTIONS:
            skip_next = True
        elif token in _OPERATORS:
            if groups[-1]:
                groups.append([])
        else:
            groups[-1].append(token)
    return [g for g in groups if g]


class CommandCheck(BaseModel):
    command: str
    allowed: bool
    reason: str | None = None


def executables_in(command: str) -> list[str]:
    """The executables a command line runs (first word of each chained command)."""
    try:
        groups = split_commands(command)
    except ValueError:
        return []
    found = []
    for tokens in groups:
        tokens = [t for t in tokens if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", t)]
        if tokens:
            found.append(tokens[0])
    return found


def validate_command(command: str, extra_allowed: Iterable[str] = ()) -> CommandCheck:
    """`extra_allowed`: executables this project itself documents (see analysis run/test commands)."""
    allowed = ALLOWED_EXECUTABLES | {e.strip() for e in extra_allowed if e.strip()}
    stripped = command.strip()
    if not stripped:
        return CommandCheck(command=command, allowed=False, reason="empty command")
    if "\n" in stripped:
        return CommandCheck(command=command, allowed=False, reason="multi-line commands are not allowed")
    if re.search(r"`|\$\(", stripped):
        return CommandCheck(command=command, allowed=False, reason="command substitution is not allowed")

    for pattern, reason in DENY_PATTERNS:
        if pattern.search(stripped):
            return CommandCheck(command=command, allowed=False, reason=reason)

    try:
        groups = split_commands(stripped)
    except ValueError as exc:
        return CommandCheck(command=command, allowed=False, reason=f"cannot parse: {exc}")
    for tokens in groups:
        # Skip leading VAR=value assignments.
        tokens = [t for t in tokens if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", t)] or tokens
        executable = tokens[0] if tokens else ""
        if "/" in executable:
            return CommandCheck(
                command=command, allowed=False,
                reason=f"run executables by name, not by path ({executable!r})",
            )
        if executable not in allowed:
            return CommandCheck(
                command=command, allowed=False, reason=f"{executable!r} is not an allowed command"
            )
    return CommandCheck(command=command, allowed=True)
